     1|/**
     2| * IVX Owner AI Watchdog UI.
     3| *
     4| * Two surfaces:
     5| * 1. <IVXWatchdogBanner /> — a compact red banner shown when the latest
     6| *    report's finalStatus is BLOCKED, SILENT_FAILURE, or VISIBLE_ERROR.
     7| *    Tapping it opens the drawer.
     8| * 2. <IVXWatchdogDrawer /> — a full-screen modal showing the last 20
     9| *    reports with every checkpoint, file:line, and fix hint. Built so the
    10| *    owner can screenshot it from a mobile device.
    11| */
    12|
    13|import React, { useEffect, useMemo, useState } from 'react';
    14|import { Modal, Pressable, ScrollView, StyleSheet, Text, View } from 'react-native';
    15|
    16|import { CHECKPOINT_ORDER, ivxAIWatchdog, type WatchdogReport, type WatchdogSnapshot } from '@/src/modules/ivx-owner-ai/services/ivxAIWatchdog';
    17|import {
    18|  analyzeBackendPostFailures,
    19|  BACKEND_POST_FAILURE_CAUSE_LABEL,
    20|  classifyWatchdogWarning,
    21|  resolveDegradedRecoveryFields,
    22|  resolveFailureBannerFields,
    23|  type AnalyzableWatchdogReport,
    24|  type BannerReportInput} from '@/src/modules/ivx-owner-ai/services/ivxBackendPostFailureAnalyzer';
    25|import { getIVXOwnerAIResolvedEndpoint, getIVXOwnerAIConfigAudit, getIVXAuthStatusSnapshot, type IVXAuthStatusSnapshot } from '@/lib/ivx-supabase-client';
    26|
    27|const CANONICAL_OWNER_AI_URL = 'https://api.ivxholding.com/api/ivx/owner-ai';
    28|
    29|function resolveDisplayOwnerAIUrl(): { url: string; forced: boolean; raw: string | null } {
    30|  let raw: string | null = null;
    31|  try {
    32|    raw = getIVXOwnerAIResolvedEndpoint();
    33|  } catch {
    34|    raw = null;
    35|  }
    36|  const trimmed = (raw ?? '').trim();
    37|  const lower = trimmed.toLowerCase();
    38|  const looksBad = !trimmed
    39|    || lower === 'undefined'
    40|    || lower === 'null'
    41|    || lower.includes('ivxtest.dev')
    42|    || lower.includes('localhost')
    43|    || lower.includes('127.0.0.1')
    44|    || lower.includes('192.168.')
    45|    || (typeof window !== 'undefined' && typeof window.location?.origin === 'string' && window.location.origin && lower.startsWith(window.location.origin.toLowerCase()));
    46|  if (looksBad) {
    47|    return { url: CANONICAL_OWNER_AI_URL, forced: true, raw };
    48|  }
    49|  return { url: trimmed, forced: false, raw };
    50|}
    51|
    52|const COLORS = {
    53|  bannerBg: '#3a0a0a',
    54|  bannerBorder: '#ff4d4f',
    55|  bannerText: '#ffd7d8',
    56|  bannerSubtext: '#ff9a9c',
    57|  pendingBg: '#2a1f05',
    58|  pendingBorder: '#f59e0b',
    59|  pendingText: '#fde68a',
    60|  drawerBg: '#0b0d10',
    61|  cardBg: '#15181d',
    62|  cardBorder: '#23272f',
    63|  passGreen: '#4ade80',
    64|  failRed: '#f87171',
    65|  pendingGrey: '#6b7280',
    66|  successBadge: '#16a34a',
    67|  infoBadge: '#2563eb',
    68|  errorBadge: '#dc2626',
    69|  blockedBadge: '#b91c1c',
    70|  silentBadge: '#7c2d12',
    71|  degradedBadge: '#d97706',
    72|  warnBannerBg: '#2a1f05',
    73|  warnBannerBorder: '#f59e0b',
    74|  warnBannerText: '#fde68a',
    75|  warnBannerSubtext: '#fbbf24',
    76|  text: '#e5e7eb',
    77|  subtext: '#9ca3af'} as const;
    78|
    79|function useWatchdogSnapshot(): WatchdogSnapshot {
    80|  const [snapshot, setSnapshot] = useState<WatchdogSnapshot>(() => ivxAIWatchdog.getSnapshot());
    81|  useEffect(() => {
    82|    void ivxAIWatchdog.hydrate();
    83|    const unsub = ivxAIWatchdog.subscribe(setSnapshot);
    84|    return () => {
    85|      unsub();
    86|    };
    87|  }, []);
    88|  return snapshot;
    89|}
    90|
    91|function useLatestReports(): WatchdogReport[] {
    92|  const snapshot = useWatchdogSnapshot();
    93|  return snapshot.finalized;
    94|}
    95|
    96|// Module-level single-instance guard. Prevents stacked HUDs caused by
    97|// duplicate route mounts, fast-refresh remounts, or accidental double renders.
    98|let HUD_INSTANCE_COUNT = 0;
    99|let BANNER_INSTANCE_COUNT = 0;
   100|
   101|const BUILD_TAG = 'hud-v2-' + (typeof __DEV__ !== 'undefined' && __DEV__ ? 'dev' : 'prod');
   102|
   103|/**
   104| * Always-visible HUD: shows tap counter, active trace count, latest report status.
   105| * Single-instance enforced — any additional mount logs a warning and renders null.
   106| *
   107| * IMPORTANT: All hooks MUST be called above the early-return for duplicate mounts.
   108| * Otherwise the first render (isPrimary=false) and the post-effect render
   109| * (isPrimary=true) would execute a different number of hooks → React throws
   110| * "Rendered more hooks than during the previous render" → white screen in Expo Go.
   111| */
   112|export function IVXWatchdogHUD({ onPress }: { onPress: () => void }): React.ReactElement | null {
   113|  // --- all hooks up-front (stable order across renders) ---
   114|  const snapshot = useWatchdogSnapshot();
   115|  const [mountTick, setMountTick] = useState<number>(0);
   116|  const [isPrimary, setIsPrimary] = useState<boolean>(false);
   117|  const [authStatus, setAuthStatus] = useState<IVXAuthStatusSnapshot | null>(null);
   118|
   119|  useEffect(() => {
   120|    HUD_INSTANCE_COUNT += 1;
   121|    const primary = HUD_INSTANCE_COUNT === 1;
   122|    setIsPrimary(primary);
   123|    const mountedAt = new Date().toISOString();
   124|    if (primary) {
   125|      console.log('[IVX_HUD] MOUNTED (primary)', mountedAt);
   126|    } else {
   127|      console.log('[IVX_HUD] DUPLICATE_MOUNT_SUPPRESSED', { mountedAt, totalInstances: HUD_INSTANCE_COUNT });
   128|    }
   129|    setMountTick(Date.now());
   130|    const interval = setInterval(() => setMountTick(Date.now()), 1000);
   131|    return () => {
   132|      clearInterval(interval);
   133|      HUD_INSTANCE_COUNT = Math.max(0, HUD_INSTANCE_COUNT - 1);
   134|      console.log('[IVX_HUD] UNMOUNTED', { at: new Date().toISOString(), remainingInstances: HUD_INSTANCE_COUNT });
   135|    };
   136|  }, []);
   137|
   138|  const urlInfo = useMemo(() => resolveDisplayOwnerAIUrl(), [mountTick]);
   139|
   140|  useEffect(() => {
   141|    if (!isPrimary) return;
   142|    let cancelled = false;
   143|    const refresh = async (): Promise<void> => {
   144|      try {
   145|        const snap = await getIVXAuthStatusSnapshot();
   146|        if (!cancelled) setAuthStatus(snap);
   147|      } catch (err) {
   148|        console.log('[IVX_HUD] auth status refresh failed:', err instanceof Error ? err.message : 'unknown');
   149|      }
   150|    };
   151|    void refresh();
   152|    const interval = setInterval(() => { void refresh(); }, 2000);
   153|    return () => { cancelled = true; clearInterval(interval); };
   154|  }, [isPrimary]);
   155|
   156|  // --- early-return for duplicate mounts AFTER all hooks ---
   157|  if (!isPrimary) return null;
   158|
   159|  const latest = snapshot.active[snapshot.active.length - 1] ?? snapshot.finalized[0] ?? null;
   160|  const statusLabel = latest ? latest.finalStatus : 'idle';
   161|  const lastCp = latest?.lastSuccessfulCheckpoint ?? '—';
   162|  const failedCp = latest?.failedCheckpoint ?? '—';
   163|  const tapLabel = snapshot.lastTap
   164|    ? `${snapshot.lastTap.at.slice(11, 19)}${snapshot.lastTap.blocked ? ` BLOCKED:${snapshot.lastTap.reason}` : ''}`
   165|    : 'no taps yet';
   166|  const color = (() => {
   167|    if (!latest) return '#6b7280';
   168|    if (latest.finalStatus === 'PENDING') return '#f59e0b';
   169|    if (latest.finalStatus === 'SUCCESS') return '#16a34a';
   170|    if (latest.finalStatus === 'DEGRADED') return '#d97706';
   171|    // Yellow for recoverable/degraded warnings, red only for true errors.
   172|    return classifyWatchdogWarning(latest as unknown as AnalyzableWatchdogReport).severity === 'error' ? '#dc2626' : '#d97706';
   173|  })();
   174|  const aliveSec = Math.floor((Date.now() - (mountTick || Date.now())) / 1000);
   175|  const issuerHost = (() => {
   176|    if (!authStatus?.issuer) return '—';
   177|    try { return new URL(authStatus.issuer).host; } catch { return authStatus.issuer; }
   178|  })();
   179|  return (
   180|    <Pressable onPress={onPress} style={[styles.hud, { borderColor: color }]} testID="ivx-watchdog-hud">
   181|      <Text style={styles.hudHeader}>● IVX WATCHDOG HUD · alive {aliveSec}s · build {BUILD_TAG}</Text>
   182|      <Text style={[styles.hudTitle, { color }]}>{statusLabel} · taps:{snapshot.tapCount} blocked:{snapshot.blockedTapCount} active:{snapshot.active.length} reports:{snapshot.finalized.length}</Text>
   183|      <Text style={styles.hudLine} selectable>resolvedOwnerAIUrl: {urlInfo.url}{urlInfo.forced ? ' (FORCED canonical)' : ''}</Text>
   184|      <Text style={styles.hudLine} selectable>
   185|        auth: tokenPresent={String(authStatus?.tokenPresent ?? 'pending')} len={authStatus?.tokenLength ?? 0} expiresIn={authStatus?.expiresInSeconds ?? 'n/a'}s
   186|      </Text>
   187|      <Text style={styles.hudLine} selectable>
   188|        issuer: {issuerHost} projectMatch={String(authStatus?.matchesFrontendSupabase ?? 'n/a')} mode={authStatus?.securityMode ?? 'n/a'} bypass={String(authStatus?.ownerBypassEnabled ?? false)} platform={authStatus?.platform ?? 'n/a'}
   189|      </Text>
   190|      {urlInfo.forced && urlInfo.raw ? <Text style={styles.hudLine} selectable>rawResolved: {urlInfo.raw}</Text> : null}
   191|      <Text style={styles.hudLine}>lastTap: {tapLabel}</Text>
   192|      <Text style={styles.hudLine}>lastSuccessful: {lastCp}  failed: {failedCp}</Text>
   193|      {latest?.fileLine ? <Text style={styles.hudLine}>file: {latest.fileLine}</Text> : null}
   194|      <Text style={styles.hudHint}>Tap to open watchdog drawer</Text>
   195|    </Pressable>
   196|  );
   197|}
   198|
   199|/**
   200| * Returns the most recent report that should drive the live banner:
   201| * any active (PENDING) trace, else the latest finalized report.
   202| */
   203|function useLatestTrackedReport(): WatchdogReport | null {
   204|  const snapshot = useWatchdogSnapshot();
   205|  if (snapshot.active.length > 0) {
   206|    return snapshot.active[snapshot.active.length - 1] ?? null;
   207|  }
   208|  return snapshot.finalized[0] ?? null;
   209|}
   210|
   211|interface BannerProps {
   212|  onPress: () => void;
   213|}
   214|
   215|/** Terminal failure states that should raise the red "IVX AI BLOCKED" banner. */
   216|const FAILURE_STATUSES: ReadonlySet<WatchdogReport['finalStatus']> = new Set([
   217|  'BLOCKED',
   218|  'SILENT_FAILURE',
   219|  'VISIBLE_ERROR',
   220|]);
   221|
   222|/** Split an "owner/file/path.ts:functionName" checkpoint owner into path + function. */
   223|function splitFileAndFunction(fileLine: string | null): { filePath: string; functionName: string } {
   224|  if (!fileLine) {
   225|    return { filePath: '—', functionName: '—' };
   226|  }
   227|  const colon = fileLine.indexOf(':');
   228|  if (colon === -1) {
   229|    return { filePath: fileLine, functionName: '—' };
   230|  }
   231|  return {
   232|    filePath: fileLine.slice(0, colon).trim() || '—',
   233|    functionName: fileLine.slice(colon + 1).trim() || '—'};
   234|}
   235|
   236|export function IVXWatchdogBanner({ onPress }: BannerProps): React.ReactElement | null {
   237|  // All hooks above the early-return — see IVXWatchdogHUD note on hook order.
   238|  const [isPrimary, setIsPrimary] = useState<boolean>(false);
   239|  const latest = useLatestTrackedReport();
   240|  const warning = useMemo(
   241|    () => (latest ? classifyWatchdogWarning(latest as unknown as AnalyzableWatchdogReport) : null),
   242|    [latest],
   243|  );
   244|  useEffect(() => {
   245|    BANNER_INSTANCE_COUNT += 1;
   246|    const primary = BANNER_INSTANCE_COUNT === 1;
   247|    setIsPrimary(primary);
   248|    if (!primary) {
   249|      console.log('[IVX_BANNER] DUPLICATE_MOUNT_SUPPRESSED', { totalInstances: BANNER_INSTANCE_COUNT });
   250|    }
   251|    return () => {
   252|      BANNER_INSTANCE_COUNT = Math.max(0, BANNER_INSTANCE_COUNT - 1);
   253|    };
   254|  }, []);
   255|  if (!isPrimary) return null;
   256|  if (!latest || !warning) return null;
   257|
   258|  // TRUTHFUL severity, not a raw finalStatus map:
   259|  //   success → never shown (no decoration on a clean answer).
   260|  //   warning (DEGRADED_RECOVERY / AUTH_REQUIRED) → YELLOW "degraded" banner.
   261|  //     A valid answer was delivered (recovered via fallback) or the owner
   262|  //     session just needs a refresh — NEVER the red "BLOCKED" alarm.
   263|  //   error (NETWORK_FAILED / TIMEOUT / PARSE_ERROR / TRUE_FAILURE) → RED banner.
   264|  // This removes the false red BACKEND_POST_FINISHED warning when a response
   265|  // exists / the request recovered via fallback / the assistant persisted.
   266|  if (warning.severity === 'success') return null;
   267|  const isError = warning.severity === 'error';
   268|  const isInProgress = warning.severity === 'info';
   269|
   270|  // IN_PROGRESS (still in-flight): show an honest WORKING banner with elapsed
   271|  // time + the last checkpoint reached. Never blank "DEGRADED" fields — a
   272|  // working request has not failed OR recovered, so failure fields are N/A.
   273|  if (isInProgress) {
   274|    const elapsedSec = Math.max(0, Math.floor((Date.now() - new Date(latest.startedAt).getTime()) / 1000));
   275|    const lastReached = latest.lastSuccessfulCheckpoint ?? 'SEND_TAP';
   276|    return (
   277|      <Pressable
   278|        onPress={onPress}
   279|        style={[styles.banner, styles.bannerInfo]}
   280|        testID="ivx-watchdog-banner"
   281|        accessibilityRole="button"
   282|      >
   283|        <Text style={[styles.bannerTitle, styles.bannerTitleInfo]}>◐ IVX AI WORKING — {warning.label}</Text>
   284|        <Text style={styles.bannerSummary} selectable>
   285|          in progress {elapsedSec}s — last reached: {lastReached}
   286|        </Text>
   287|        <Text style={styles.bannerLine} selectable>state: WORKING (not failed, not recovered)</Text>
   288|        <Text style={styles.bannerLine} selectable>traceId: {latest.traceId}</Text>
   289|        <Text style={styles.bannerLine} selectable>lastReached: {lastReached}</Text>
   290|        <Text style={styles.bannerLine} selectable>elapsed: {elapsedSec}s</Text>
   291|        <Text style={styles.bannerHint}>Tap to open watchdog drawer.</Text>
   292|      </Pressable>
   293|    );
   294|  }
   295|
   296|  // DEGRADED_RECOVERY (yellow, recovered via fallback): show the REAL recovery
   297|  // metadata. "—" is replaced with UNKNOWN_WITH_REASON so a recovered request
   298|  // never shows blank diagnostic fields (owner spec).
   299|  if (!isError && warning.classification === 'DEGRADED_RECOVERY') {
   300|    const fields = resolveDegradedRecoveryFields(latest as unknown as BannerReportInput);
   301|    return (
   302|      <Pressable
   303|        onPress={onPress}
   304|        style={[styles.banner, styles.bannerWarn]}
   305|        testID="ivx-watchdog-banner"
   306|        accessibilityRole="button"
   307|      >
   308|        <Text style={[styles.bannerTitle, styles.bannerTitleWarn]}>▲ IVX AI DEGRADED — {warning.classification} ({warning.label})</Text>
   309|        <Text style={styles.bannerSummary} selectable>
   310|          recovered via fallback — a real answer was delivered.
   311|        </Text>
   312|        <Text style={styles.bannerLine} selectable>recoveredViaFallback: {fields.recoveredViaFallback}</Text>
   313|        <Text style={styles.bannerLine} selectable>degradedRoute: {fields.degradedRoute}</Text>
   314|        <Text style={styles.bannerLine} selectable>recoveredRoute: {fields.recoveredRoute}</Text>
   315|        <Text style={styles.bannerLine} selectable>statusCode: {fields.statusCode}</Text>
   316|        <Text style={styles.bannerLine} selectable>classification: {fields.classification}</Text>
   317|        <Text style={styles.bannerLine} selectable>reason: {fields.reason}</Text>
   318|        <Text style={styles.bannerLine} selectable>traceId: {latest.traceId}</Text>
   319|        <Text style={styles.bannerLine} selectable>lastSuccessful: {fields.lastSuccessful}</Text>
   320|        <Text style={styles.bannerHint}>Tap to open watchdog drawer.</Text>
   321|      </Pressable>
   322|    );
   323|  }
   324|
   325|  const failureFields = resolveFailureBannerFields(latest as unknown as BannerReportInput);
   326|  const titlePrefix = isError ? '● IVX AI BLOCKED' : '▲ IVX AI DEGRADED';
   327|
   328|  return (
   329|    <Pressable
   330|      onPress={onPress}
   331|      style={[styles.banner, isError ? null : styles.bannerWarn]}
   332|      testID="ivx-watchdog-banner"
   333|      accessibilityRole="button"
   334|    >
   335|      <Text style={[styles.bannerTitle, isError ? null : styles.bannerTitleWarn]}>{titlePrefix} — {warning.classification} ({warning.label})</Text>
   336|      <Text style={styles.bannerSummary} selectable>
   337|        {failureFields.lastSuccessful} ok → {failureFields.checkpoint} failed: {failureFields.reason}
   338|      </Text>
   339|      <Text style={styles.bannerLine} selectable>checkpoint: {failureFields.checkpoint}</Text>
   340|      <Text style={styles.bannerLine} selectable>traceId: {latest.traceId}</Text>
   341|      <Text style={styles.bannerLine} selectable>file: {failureFields.filePath}</Text>
   342|      <Text style={styles.bannerLine} selectable>function: {failureFields.functionName}</Text>
   343|      <Text style={styles.bannerLine} selectable>reason: {failureFields.reason}</Text>
   344|      <Text style={styles.bannerLine} selectable>nextFix: {failureFields.nextFix}</Text>
   345|      <Text style={styles.bannerLine} selectable>statusCode: {failureFields.statusCode}</Text>
   346|      <Text style={styles.bannerLine} selectable>backendResponse: {failureFields.backendResponse}</Text>
   347|      <Text style={styles.bannerLine} selectable>lastSuccessful: {failureFields.lastSuccessful}</Text>
   348|      <Text style={styles.bannerLine} selectable>failedCheckpoint: {failureFields.checkpoint}</Text>
   349|      <Text style={styles.bannerHint}>Tap to open watchdog drawer.</Text>
   350|    </Pressable>
   351|  );
   352|}
   353|
   354|interface DrawerProps {
   355|  visible: boolean;
   356|  onClose: () => void;
   357|}
   358|
   359|export function IVXWatchdogDrawer({ visible, onClose }: DrawerProps): React.ReactElement {
   360|  const snapshot = useWatchdogSnapshot();
   361|  const reports: WatchdogReport[] = useMemo(
   362|    () => [...snapshot.active.slice().reverse(), ...snapshot.finalized],
   363|    [snapshot.active, snapshot.finalized],
   364|  );
   365|  return (
   366|    <Modal visible={visible} animationType="slide" onRequestClose={onClose} presentationStyle="pageSheet">
   367|      <View style={styles.drawer}>
   368|        <View style={styles.drawerHeader}>
   369|          <Text style={styles.drawerTitle}>IVX Owner AI watchdog</Text>
   370|          <Pressable onPress={onClose} style={styles.closeBtn} testID="ivx-watchdog-close">
   371|            <Text style={styles.closeBtnText}>Close</Text>
   372|          </Pressable>
   373|        </View>
   374|        <View style={styles.drawerToolbar}>
   375|          <Text style={styles.drawerToolbarText}>Last {reports.length} report(s) — newest first</Text>
   376|          <Pressable
   377|            onPress={() => {
   378|              void ivxAIWatchdog.clear();
   379|            }}
   380|            style={styles.clearBtn}
   381|            testID="ivx-watchdog-clear"
   382|          >
   383|            <Text style={styles.clearBtnText}>Clear</Text>
   384|          </Pressable>
   385|        </View>
   386|        <ScrollView contentContainerStyle={styles.drawerContent}>
   387|          <BackendPostFailureAnalysisCard reports={snapshot.finalized} />
   388|          {reports.length === 0 ? (
   389|            <Text style={styles.emptyText}>No reports yet. Send a message to generate one.</Text>
   390|          ) : (
   391|            reports.map((report) => <ReportCard key={report.traceId} report={report} />)
   392|          )}
   393|        </ScrollView>
   394|      </View>
   395|    </Modal>
   396|  );
   397|}
   398|
   399|/**
   400| * Root-cause grouping: traces every BACKEND_POST_FINISHED failure across the
   401| * persisted reports, groups by cause, and shows the top 5 by frequency with
   402| * counts + status codes + the latest trace id as evidence.
   403| */
   404|function BackendPostFailureAnalysisCard({ reports }: { reports: WatchdogReport[] }): React.ReactElement | null {
   405|  const analysis = useMemo(
   406|    () => analyzeBackendPostFailures(reports as unknown as AnalyzableWatchdogReport[]),
   407|    [reports],
   408|  );
   409|  if (analysis.totalFailures === 0) return null;
   410|  return (
   411|    <View style={styles.analysisCard}>
   412|      <Text style={styles.analysisTitle}>BACKEND_POST_FINISHED — root-cause grouping</Text>
   413|      <Text style={styles.analysisSubtitle}>
   414|        {analysis.totalFailures} failure(s) across last {analysis.totalReports} report(s) · top {Math.min(5, analysis.top5.length)} causes
   415|      </Text>
   416|      {analysis.top5.map((group, idx) => (
   417|        <View key={group.cause} style={styles.analysisRow}>
   418|          <Text style={styles.analysisRank}>{idx + 1}.</Text>
   419|          <View style={styles.analysisBody}>
   420|            <Text style={styles.analysisCause} selectable>
   421|              {BACKEND_POST_FAILURE_CAUSE_LABEL[group.cause]} — {group.count}×
   422|            </Text>
   423|            <Text style={styles.analysisMeta} selectable>
   424|              status: {group.statusCodes.length > 0 ? group.statusCodes.join(', ') : '—'} · latest trace: {group.traceIds[0] ?? '—'}
   425|            </Text>
   426|            <Text style={styles.analysisMeta} selectable numberOfLines={2}>
   427|              e.g. {group.sampleReason || '—'}
   428|            </Text>
   429|          </View>
   430|        </View>
   431|      ))}
   432|    </View>
   433|  );
   434|}
   435|
   436|function ReportCard({ report }: { report: WatchdogReport }): React.ReactElement {
   437|  const warning = useMemo(
   438|    () => classifyWatchdogWarning(report as unknown as AnalyzableWatchdogReport),
   439|    [report],
   440|  );
   441|  const badgeStyle = useMemo(() => {
   442|    // Color by TRUTHFUL severity: green success · yellow degraded/auth-recoverable
   443|    // · red real failure. Never a red badge when the request actually recovered.
   444|    if (report.finalStatus === 'PENDING') return { backgroundColor: COLORS.pendingGrey };
   445|    if (warning.severity === 'success') return { backgroundColor: COLORS.successBadge };
   446|    if (warning.severity === 'info') return { backgroundColor: COLORS.infoBadge };
   447|    if (warning.severity === 'warning') return { backgroundColor: COLORS.degradedBadge };
   448|    return { backgroundColor: COLORS.errorBadge };
   449|  }, [report.finalStatus, warning.severity]);
   450|
   451|  const orderedCheckpoints = useMemo(() => {
   452|    const byName = new Map(report.checkpoints.map((cp) => [cp.name, cp] as const));
   453|    return CHECKPOINT_ORDER.map((name) => byName.get(name)).filter((cp): cp is NonNullable<typeof cp> => Boolean(cp));
   454|  }, [report.checkpoints]);
   455|
   456|  return (
