    28|  onError: (error: string) => void;
    29|  onComplete: (finalText: string, model: string, source: string) => void;
    30|};
    31|
    32|export type StreamPublicChatInput = {
    33|  message: string;
    34|  history: PublicChatHistoryItem[];
